package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.format;

import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.ImplementationState;
import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.resource.*;
import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill.*;

/** Parameter-bearing English/Simplified-Chinese formatter for every exposed P04 skill effect. */
public final class SkillFormatter {
	public enum Language { ENGLISH, SIMPLIFIED_CHINESE }
	public String format(SkillSpec skill,Language language){if(skill==null||language==null)throw new IllegalArgumentException("skill and language required");if(!skill.typed()||skill.implementationState()!=ImplementationState.IMPLEMENTED)return language==Language.ENGLISH?"Unsupported skill":"不支持的技能";boolean zh=language==Language.SIMPLIFIED_CHINESE;StringBuilder out=new StringBuilder(skill.displayName().text()).append(zh?"：":" : ");out.append(zh?"主动；":"Active; ").append(target(skill,zh)).append(zh?"；":"; ").append(effect(skill.effects().primary(),zh));if(skill.effects().secondary()!=null)out.append(zh?"；主效果成功后立即":"; then immediately on primary success ").append(effect(skill.effects().secondary().effect(),zh));out.append(zh?"；":"; ").append(cost(skill.cost(),zh));if(skill.delivery() instanceof DirectDeliverySpec)out.append(zh?(((DirectDeliverySpec)skill.delivery()).requiresLineOfSight()?"；需要视线。":"；不要求视线。"):(((DirectDeliverySpec)skill.delivery()).requiresLineOfSight()?"; requires line of sight.":"; line of sight not required."));else out.append(zh?"；投递：":"; delivery: ").append(skill.delivery().variantKey()).append('。');return out.toString();}
	private static String target(SkillSpec s,boolean zh){return zh?"选择 "+s.targeting().range()+" 格内目标（"+s.targeting().selector().variantKey()+"/"+s.targeting().coverage().variantKey()+"/"+s.targeting().filter().variantKey()+"）":"choose target within "+s.targeting().range()+" tile(s) ("+s.targeting().selector().variantKey()+"/"+s.targeting().coverage().variantKey()+"/"+s.targeting().filter().variantKey()+")";}
	private static String effect(EffectSpec e,boolean zh){if(e instanceof DirectDamageEffectSpec)return zh?"造成 "+value(((DirectDamageEffectSpec)e).amount())+" 点原生直接伤害":"deal "+value(((DirectDamageEffectSpec)e).amount())+" native direct damage";if(e instanceof PercentMaxHpDamageEffectSpec){PercentMaxHpDamageEffectSpec x=(PercentMaxHpDamageEffectSpec)e;return (zh?"造成最大生命值 ":"deal ")+x.percent()+"%"+(zh?" 伤害，上限 ":" max-HP damage, cap ")+x.absoluteCap()+" ("+x.protectedTargetPolicy()+")";}if(e instanceof MissingHpDamageEffectSpec){MissingHpDamageEffectSpec x=(MissingHpDamageEffectSpec)e;return (zh?"造成基础 ":"deal base ")+value(x.baseAmount())+(zh?" + 已损生命值×":" + missing HP x ")+x.missingHpNumerator()+"/"+x.missingHpDenominator()+(zh?" 伤害，上限 ":", cap ")+x.absoluteCap();}if(e instanceof ExecuteEffectSpec){ExecuteEffectSpec x=(ExecuteEffectSpec)e;return (zh?"生命值不高于 ":"execute at ")+x.hpPercentThreshold()+"% ("+x.protectedTargetPolicy()+")";}if(e instanceof ApplyStatusEffectSpec){ApplyStatusEffectSpec x=(ApplyStatusEffectSpec)e;return (zh?"施加状态 ":"apply status ")+x.status()+" intensity="+value(x.intensity())+" duration="+x.duration().kind()+":"+x.duration().turns()+" stacking="+x.stacking();}if(e instanceof PushEffectSpec)return movement("PUSH",((PushEffectSpec)e).distance(),((PushEffectSpec)e).collisionPolicy(),zh);if(e instanceof PullEffectSpec)return movement("PULL",((PullEffectSpec)e).distance(),((PullEffectSpec)e).collisionPolicy(),zh);if(e instanceof ThrowEffectSpec)return movement("THROW",((ThrowEffectSpec)e).distance(),((ThrowEffectSpec)e).collisionPolicy(),zh);if(e instanceof DashEffectSpec)return "DASH distance="+((DashEffectSpec)e).maximumDistance()+" path="+((DashEffectSpec)e).pathPolicy();if(e instanceof TeleportEffectSpec)return "TELEPORT range="+((TeleportEffectSpec)e).maximumRange()+" destination="+((TeleportEffectSpec)e).destinationPolicy();if(e instanceof SwapPositionEffectSpec)return "SWAP_POSITION legality="+((SwapPositionEffectSpec)e).legalityPolicy();if(e instanceof HealEffectSpec)return (zh?"治疗 ":"heal ")+value(((HealEffectSpec)e).amount());if(e instanceof BarrierEffectSpec)return (zh?"获得屏障 ":"gain barrier ")+value(((BarrierEffectSpec)e).amount())+" ("+((BarrierEffectSpec)e).overflowPolicy()+")";if(e instanceof TemporaryHpEffectSpec){TemporaryHpEffectSpec x=(TemporaryHpEffectSpec)e;return (zh?"获得临时生命 ":"gain temporary HP ")+value(x.amount())+" duration="+x.duration().turns()+" stacking="+x.stacking();}if(e instanceof MitigateEffectSpec){MitigateEffectSpec x=(MitigateEffectSpec)e;return (zh?"减伤 ":"mitigate ")+x.percent()+"% duration="+x.duration().turns();}if(e instanceof RedirectDamageEffectSpec){RedirectDamageEffectSpec x=(RedirectDamageEffectSpec)e;return (zh?"重定向伤害 ":"redirect damage ")+x.percent()+"% recipient="+x.recipient()+" duration="+x.duration().turns();}if(e instanceof CleanseEffectSpec){CleanseEffectSpec x=(CleanseEffectSpec)e;return (zh?"净化 ":"cleanse ")+x.filter().kind()+":"+x.filter().status()+" max="+x.maximumCount();}if(e instanceof ResourceOperationEffectSpec)return resource(((ResourceOperationEffectSpec)e).operation(),zh);return e.variantKey().name();}
	private static String movement(String key,int distance,Object policy,boolean zh){return (zh?"移动效果 ":"movement ")+key+" distance="+distance+" collision="+policy;}
	public static String resource(ResourceOperationSpec op,boolean zh){String lead=zh?"资源操作 ":"resource operation ";if(op instanceof ConvertResourceSpec){ConvertResourceSpec x=(ConvertResourceSpec)op;return lead+"CONVERT "+x.source().lastKnownDisplayName()+" -"+x.sourceAmount()+" -> "+x.target().lastKnownDisplayName()+" +"+x.targetAmount()+" ("+x.conversionPolicy()+")";}return lead+op.variant()+" resource="+op.referencedResources().get(0).lastKnownDisplayName();}
	private static String cost(CostSpec c,boolean zh){if(c instanceof NoCostSpec)return zh?"无消耗":"no cost";if(c instanceof ResourceCostSpec)return (zh?"消耗资源 ":"resource cost ")+((ResourceCostSpec)c).resource().lastKnownDisplayName()+" "+((ResourceCostSpec)c).amount();if(c instanceof HpCostSpec)return (zh?"生命消耗 ":"HP cost ")+((HpCostSpec)c).amount()+" min="+((HpCostSpec)c).minimumRemainingHp()+" "+((HpCostSpec)c).lethalPolicy();if(c instanceof ActionTimeCostSpec)return (zh?"行动时间 ":"action time ")+((ActionTimeCostSpec)c).turns();if(c instanceof CooldownCostSpec)return (zh?"冷却 ":"cooldown ")+((CooldownCostSpec)c).turns();if(c instanceof ItemCostSpec)return (zh?"物品消耗 ":"item cost ")+((ItemCostSpec)c).itemFilter().category()+" x"+((ItemCostSpec)c).count();return c.variantKey();}
	private static String value(ValueSpec v){if(v instanceof FixedValueSpec)return Integer.toString(((FixedValueSpec)v).value());ScaledValueSpec x=(ScaledValueSpec)v;return x.base()+"+("+x.source().variantKey()+"*"+x.numerator()+"/"+x.denominator()+") ["+x.minimum()+","+x.maximum()+"]";}
}
